const R="https://cderses.github.io/normal-cabinet-gyodong/rooms.json",T=9000,C=20000;let cache={at:0,body:null};function iso(d){return d.slice(0,4)+"-"+d.slice(4,6)+"-"+d.slice(6,8)}function parse(t){const out=[],re=/BEGIN:VEVENT([\s\S]*?)END:VEVENT/g,u=String(t).replace(/\r?\n[ \t]/g,"");let x;while((x=re.exec(u))){const b=x[1],s=/DTSTART[^:\r\n]*:(\d{8})/.exec(b),e=/DTEND[^:\r\n]*:(\d{8})/.exec(b);if(s&&e)out.push([iso(s[1]),iso(e[1])])}return out}async function get(u){const c=new AbortController(),h=setTimeout(()=>c.abort(),T);try{const r=await fetch(u,{signal:c.signal});if(!r.ok)throw new Error("HTTP "+r.status);return r.text()}finally{clearTimeout(h)}}async function build(){const list=JSON.parse(await get(R)),rooms={},errors=[];const res=await Promise.all(list.map(r=>get(r.ical_url).then(t=>[r.listing_id,parse(t)]).catch(e=>{errors.push({listing_id:r.listing_id,error:String(e)});return[r.listing_id,[]]})));res.forEach(p=>{rooms[p[0]]={blocked:p[1]}});return{updated_at:new Date(Date.now()+324e5).toISOString().slice(0,19)+"+09:00",rooms,errors}}export default{async fetch(){const h={"content-type":"application/json","access-control-allow-origin":"*"};try{if(!cache.body||Date.now()-cache.at>C)cache={at:Date.now(),body:await build()};return new Response(JSON.stringify(cache.body),{headers:h})}catch(e){return new Response(JSON.stringify({error:"upstream_failed",detail:String(e)}),{status:502,headers:h})}}};
